insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g1_fa_v1'
from (values
('117.105.b.1.A',2,'Two apples in a bowl look almost the same but one is bigger. Noticing this uses your...','["senses to compare", "nose to read", "mouth to sing", "ears to count"]'::jsonb,0,'Artists notice how things are alike and different.','original'),
('117.105.b.1.A',3,'Describing how a rough tree bark is different from smooth glass uses the sense of...','["hearing", "touch", "smell", "taste"]'::jsonb,1,'Touch tells texture.','original'),
('117.105.b.1.B',2,'The way a surface feels, like fuzzy or smooth, is its...','["voice", "beat", "texture", "tempo"]'::jsonb,2,'Texture is how something feels.','original'),
('117.105.b.1.B',3,'A cube or a ball that you can hold is an example of...','["line", "rhythm", "tempo", "form"]'::jsonb,3,'Form is three-dimensional.','original'),
('117.105.b.1.B',3,'Putting a big shape on one side and a big shape on the other side makes a picture with...','["balance", "noise", "rhythm", "tempo"]'::jsonb,0,'Balance means equal weight.','original'),
('117.105.b.2.A',2,'Mixing dots, curvy lines, and squares to make a new creature is...','["copying a photo", "inventing an image", "counting", "reading a story"]'::jsonb,1,'Inventing means making something new.','original'),
('117.105.b.2.A',3,'Choosing red, orange, and yellow to paint a sunset is a choice about...','["pitch", "tempo", "color", "rhythm"]'::jsonb,2,'Colors can be chosen.','original'),
('117.105.b.2.B',3,'Placing squares in neat rows to make a design is an...','["mistake", "random scribble", "accident", "orderly arrangement"]'::jsonb,3,'Orderly means in an organized way.','original'),
('117.105.b.2.C',2,'Using scissors carefully to cut paper shapes is building...','["manipulative skills", "swimming skills", "reading speed", "dance steps"]'::jsonb,0,'Small hand movements are manipulative skills.','original'),
('117.105.b.2.C',3,'Pressing a rubber stamp into ink and onto paper makes a...','["song", "print", "poem", "play"]'::jsonb,1,'Prints are made by pressing.','original'),
('117.105.b.3.A',2,'A painting of a sunny park shows the idea of...','["nothing", "a math problem", "a happy day outdoors", "a storm at sea"]'::jsonb,2,'Artworks express ideas.','original'),
('117.105.b.3.A',3,'The same flower can be shown by a drawing, a painting, or a sculpture. These different tools are called...','["meals", "notes", "steps", "media"]'::jsonb,3,'Media are art materials.','original'),
('117.105.b.3.B',3,'Artists in different countries and long ago made art. This shows art is made by...','["people all over the world and through time", "only machines", "only adults today", "only one country"]'::jsonb,0,'Art is global and historical.','original'),
('117.105.b.3.C',2,'A decorated plate or a colorful poster shows how art is used in...','["nowhere", "everyday life", "only museums", "only space"]'::jsonb,1,'Art is part of daily life.','original'),
('117.105.b.3.D',3,'Using a ruler to measure and draw equal squares links art with...','["singing", "cooking", "math", "swimming"]'::jsonb,2,'Measuring is a math skill.','original'),
('117.105.b.4.A',2,'Telling the class why you chose blue for the sky in your picture is...','["erasing your picture", "hiding your picture", "losing your picture", "explaining your artwork"]'::jsonb,3,'Artists explain choices.','original'),
('117.105.b.4.B',3,'A building where paintings and sculptures are displayed for visitors is an art...','["museum", "garage", "bakery", "post office"]'::jsonb,0,'Museums collect art.','original'),
('117.105.b.4.B',3,'Looking at pictures of artworks on a computer from a museum is visiting a...','["bakery", "virtual museum", "kitchen", "zoo"]'::jsonb,1,'Virtual means online.','original'),
('117.105.b.4.C',3,'Keeping your drawings together in a folder to show later is making a...','["racecourse", "map", "portfolio", "sandwich"]'::jsonb,2,'Portfolios store art.','original'),
('117.106.b.1.A',2,'The voice used to sound out a song is the...','["whispering voice", "inner voice", "calling voice", "singing voice"]'::jsonb,3,'The singing voice makes melody.','original'),
('117.106.b.1.A',3,'A child''s singing voice is usually...','["higher than an adult man''s voice", "silent", "lower than a drum", "the same as a tuba"]'::jsonb,0,'Children sing higher.','original'),
('117.106.b.1.B',2,'A trumpet and a trombone are in which instrument family?','["strings", "brass", "woodwinds", "percussion"]'::jsonb,1,'Brass instruments are metal horns.','original'),
('117.106.b.1.B',3,'A flute and a clarinet are in the...','["string family", "percussion family", "woodwind family", "brass family"]'::jsonb,2,'Woodwinds are blown.','original'),
('117.106.b.1.B',3,'A xylophone and a snare drum are in the...','["string family", "woodwind family", "brass family", "percussion family"]'::jsonb,3,'Percussion are struck.','original'),
('117.106.b.1.C',3,'The musical word for fast is...','["allegro", "forte", "largo", "piano"]'::jsonb,0,'Allegro means fast.','original'),
('117.106.b.1.C',3,'The musical word for slow is...','["piano", "largo", "allegro", "forte"]'::jsonb,1,'Largo means slow.','original'),
('117.106.b.1.C',3,'The musical word for loud is...','["piano", "allegro", "forte", "largo"]'::jsonb,2,'Forte means loud.','original'),
('117.106.b.1.C',3,'The musical word for soft is...','["allegro", "forte", "largo", "piano"]'::jsonb,3,'Piano means soft.','original'),
('117.106.b.1.D',3,'A song with a first part that repeats and then a different part uses the pattern...','["ab", "all the same", "zz", "xy"]'::jsonb,0,'ab means two different sections.','original'),
('117.106.b.1.D',4,'A song plays its first section twice, then a new section, then the first section once more. Its pattern is...','["abba", "aaba", "bbbb", "abcd"]'::jsonb,1,'aaba repeats a then contrasts.','original'),
('117.106.b.2.A',3,'A quarter note gets how many beats in a simple pattern?','["four beats", "none", "one beat", "ten beats"]'::jsonb,2,'Quarter note is one beat.','original'),
('117.106.b.2.A',4,'Two paired eighth notes together take the same time as one...','["dotted whole", "half rest", "whole note", "quarter note"]'::jsonb,3,'Two eighths equal one quarter.','original'),
('117.106.b.2.B',4,'The pentatonic scale has how many different tones?','["five", "ten", "two", "twelve"]'::jsonb,0,'Pentatonic means five tones.','original'),
('117.106.b.2.B',4,'Writing three tones in order so you can sing them is writing a...','["picture", "melodic pattern", "poem", "rhythmic pattern"]'::jsonb,1,'Melody is about pitch.','original'),
('117.106.b.3.A',2,'Singing in tune with your class is singing...','["silently", "sadly", "tunefully", "slowly only"]'::jsonb,2,'Tunefully means on pitch.','original'),
('117.106.b.3.B',3,'Playing a folk song from another country shows music from a different...','["weather", "season", "shape", "culture"]'::jsonb,3,'Songs reflect cultures.','original'),
('117.106.b.3.C',3,'Moving only your arms while standing still is a...','["non-locomotor movement", "run", "locomotor movement", "march"]'::jsonb,0,'Non-locomotor stays in place.','original'),
('117.106.b.3.D',4,'A short pattern that keeps repeating under a song is a...','["map", "rhythmic ostinato", "picture", "story"]'::jsonb,1,'An ostinato repeats.','original'),
('117.106.b.3.D',3,'Tapping the steady beat while a friend taps the words'' rhythm is doing...','["a nap", "a mistake", "part work", "a puzzle"]'::jsonb,2,'Part work uses different parts together.','original'),
('117.106.b.3.E',3,'If the class plays a song softly and slowly, they are using...','["forte and allegro", "forte and largo", "piano and allegro", "piano and largo"]'::jsonb,3,'Soft and slow match piano and largo.','original'),
('117.106.b.4.A',3,'Making your own pattern with quarter notes and paired eighth notes is creating a...','["rhythmic pattern", "word pattern", "color pattern", "shape pattern"]'::jsonb,0,'Rhythm uses long and short sounds.','original'),
('117.106.b.4.B',3,'Choosing three notes to make your own short tune is creating a...','["stage set", "melodic pattern", "costume", "painting"]'::jsonb,1,'Melody is made of pitches.','original'),
('117.106.b.4.C',3,'Trying a new sound on a classroom instrument is...','["ignoring music", "erasing music", "exploring a new musical idea", "stopping music"]'::jsonb,2,'Exploring finds new ideas.','original'),
('117.106.b.5.A',2,'A song you sing at a flag ceremony is a...','["cartoon only", "lullaby only", "jingle only", "patriotic song"]'::jsonb,3,'Patriotic songs honor the nation.','original'),
('117.106.b.5.B',3,'Feeling the steady beat in an old folk tune and a new song shows beat is found in music from...','["many times and cultures", "only one place", "only one time", "only machines"]'::jsonb,0,'Beat appears everywhere.','original'),
('117.106.b.5.C',3,'Counting beats in a song links music with...','["swimming", "math", "cooking", "painting only"]'::jsonb,1,'Counting is math.','original'),
('117.106.b.6.A',2,'At a school concert, you show good audience behavior by...','["running", "talking loudly", "listening quietly", "calling out"]'::jsonb,2,'Audiences are respectful.','original'),
('117.106.b.6.B',3,'If you hear a pattern of long-short-short in a song and name it correctly, you are...','["dancing", "resting", "painting", "recognizing a rhythmic element"]'::jsonb,3,'Naming patterns uses music words.','original'),
('117.106.b.6.C',3,'Hearing two songs that are both loud shows they are the...','["same in dynamics", "slow", "different in dynamics", "silent"]'::jsonb,0,'Both loud means same.','original'),
('117.106.b.6.D',3,'Showing with arm movements that the music is getting faster is responding...','["by sleeping", "through movement", "with a pen", "with a paintbrush"]'::jsonb,1,'Movement shows response.','original'),
('117.107.b.1.A',2,'Playing pretend helps you build...','["noise only", "fear", "confidence", "nothing"]'::jsonb,2,'Dramatic play builds confidence.','original'),
('117.107.b.1.B',3,'Walking in a big circle and keeping space around you uses...','["painting", "counting", "spelling", "spatial awareness"]'::jsonb,3,'Spatial awareness is knowing space.','original'),
('117.107.b.1.C',2,'Hopping like a bunny and making a hop sound is imitating actions and...','["sounds", "numbers", "words only", "colors"]'::jsonb,0,'Imitating includes sounds.','original'),
('117.107.b.1.D',3,'Pretending to be a tree swaying in the wind is creating an...','["machine", "inanimate object", "person", "animal"]'::jsonb,1,'Trees are non-living in drama class.','original'),
('117.107.b.1.D',3,'Acting like a barking dog is imitating an...','["rock", "inanimate object", "animate object", "chair"]'::jsonb,2,'Animals are animate.','original'),
('117.107.b.2.A',2,'Using your voice safely in a play means...','["never speaking", "screaming nonstop", "whispering all day", "using a strong voice without hurting your throat"]'::jsonb,3,'Safe voice use protects you.','original'),
('117.107.b.2.B',3,'Acting like a grandmother at a pretend tea party is creating a role through...','["imitation", "subtraction", "division", "sleeping"]'::jsonb,0,'Imitating a person makes a role.','original'),
('117.107.b.2.C',3,'Acting out The Three Little Pigs with your class is dramatizing a...','["math fact", "simple story", "map", "science lab"]'::jsonb,1,'Dramatizing is acting out.','original'),
('117.107.b.2.D',3,'Acting out the words of a nursery rhyme is dramatizing a...','["menu", "map", "poem", "recipe"]'::jsonb,2,'Poems can be dramatized.','original'),
('117.107.b.3.A',3,'When you decide your play happens in a snowy forest, you are discussing the play''s...','["lunch", "shoes", "homework", "location and climate"]'::jsonb,3,'Setting includes place and weather.','original'),
('117.107.b.3.B',3,'Using chairs and tables to build a ship for pretend is adapting the...','["environment", "clock", "map", "calendar"]'::jsonb,0,'Common objects can become sets.','original'),
('117.107.b.3.C',3,'Practicing the same scene several times before the show is...','["reading", "rehearsal", "recipe", "recess"]'::jsonb,1,'Rehearsal is practice.','original'),
('117.107.b.3.D',2,'A good cast mate listens and shares the stage. This is...','["ignoring", "competition", "cooperation", "bullying"]'::jsonb,2,'Cooperation helps a play.','original'),
('117.107.b.4.A',3,'Pretending to be a school bus driver and a crossing guard in a skit is imitating...','["ancient times", "space travel", "cartoons only", "school and community life"]'::jsonb,3,'Skits can show community roles.','original'),
('117.107.b.4.B',4,'A tale with talking animals that teaches a lesson is a...','["fable", "recipe", "math problem", "weather report"]'::jsonb,0,'Fables teach lessons.','original'),
('117.107.b.4.B',4,'A very old story that explains why something in nature happens is a...','["map", "myth", "math fact", "shopping list"]'::jsonb,1,'Myths explain the world.','original'),
('117.107.b.5.A',2,'Which is good audience behavior at a play?','["use a loud toy", "walk around", "clap at the end", "talk during the scene"]'::jsonb,2,'Respectful audiences stay quiet.','original'),
('117.107.b.5.B',3,'After the skit, saying what part you liked best is...','["erasing the drama", "hiding the drama", "ignoring the drama", "discussing the drama"]'::jsonb,3,'Discussion shares thoughts.','original'),
('117.107.b.5.C',3,'Adding music and a costume to a play uses sound and visual components to...','["make the story clearer", "hurt the audience", "stop the story", "hide the actors"]'::jsonb,0,'Components enhance stories.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
